type Forme interface{ Aire() float64 }
type Carre struct{ C float64 }
type Rect struct{ L, H float64 }

func (c Carre) Aire() float64 { return c.C * c.C }
func (r Rect) Aire() float64  { return r.L * r.H }

func main() {
    total := 0.0
    for _, f := range []Forme{Carre{2}, Rect{2, 3}} {
        total += f.Aire()
    }
    fmt.Println(total)
}

func decrire(v any) string {
    switch x := v.(type) {
    case int:
        return fmt.Sprint("entier ", x)
    case string:
        return "texte " + x
    default:
        return "autre"
    }
}

func main() {
    fmt.Println(decrire(4), decrire("go"), decrire(1.5))
}
